use crate::character::{Anchor, CharacterPack};
use std::collections::HashMap;

pub fn get_backdrop_b64(name: &str) -> Option<&'static str> {
    match name.to_lowercase().as_str() {
        "pastoral" => Some(""),
        "room" => Some(""),
        "field" => Some(""),
        _ => None,
    }
}

pub fn load_woodring_characters() -> Vec<CharacterPack> {
    vec![
        load_armando(),
        load_dan(),
        load_tiki(),
        load_tongtyed(),
    ]
}

